 'use strict';
// MapLibre owns navigation; the climate source and click values use the original grid.
class GeographicMap {
  constructor(onInspect,onHover) {
    this.regions={world:[[-58,-179],[78,179]],europe:[[34,-25],[72,45]],usa:[[24,-125],[50,-66]]};
    this.usaViews={contiguous:this.regions.usa,alaska:[[51,-170],[72,-130]],hawaii:[[18,-161],[23,-154]]};
    this.region='world';this.usaView='contiguous';this.field=null;this.selected=null;this.display='smooth';this.revision=0;this.tileRequests=new Map();this.tileSequence=0;
    this.tileWorker=new Worker('map-tiles-worker.js?v=20');
    this.tileWorker.onmessage=({data})=>{const pending=this.tileRequests.get(data.id);if(!pending)return;this.tileRequests.delete(data.id);pending.detach();if(data.error)pending.reject(new Error(data.error));else pending.resolve({data:data.buffer});};
    this.tileWorker.onerror=()=>{for(const pending of this.tileRequests.values()){pending.detach();pending.reject(new Error('Climate tile rendering failed. Reload the page.'));}this.tileRequests.clear();};
    maplibregl.addProtocol('comfy-climate',(request,controller)=>this.requestTile(request.url,controller.signal));
    this.map=new maplibregl.Map({container:'map',style:'assets/basemap-style.json?v=11',center:[0,20],zoom:1.5,minZoom:0,maxZoom:16,renderWorldCopies:true,dragRotate:false,pitchWithRotate:false,touchPitch:false,attributionControl:false,fadeDuration:0,canvasContextAttributes:{preserveDrawingBuffer:true}});
    this.map.touchZoomRotate.disableRotation();
    this.map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');
    this.map.addControl(new maplibregl.ScaleControl({maxWidth:110,unit:'metric'}),'bottom-left');
    this.map.addControl(new maplibregl.AttributionControl({compact:true,customAttribution:'Climate: ERA5 / ECMWF · Export borders: Natural Earth'}),'bottom-right');
    this.ready=new Promise(resolve=>this.map.once('style.load',()=>{this.loaded=true;this.installClimate();this.installStates();resolve();}));
    this.map.on('error',event=>{if(/openfreemap|glyph|sprite|tile/i.test(event.error?.message||'')){const hint=document.getElementById('map-cartography-status');if(hint)hint.textContent='Some map labels could not load. Climate values are still available. Reload to retry.';}});
    this.map.on('click',e=>{const feature=this.map.getLayer('city-filter-points')?this.map.queryRenderedFeatures(e.point,{layers:['city-filter-points']})[0]:null;const coords=feature?.geometry?.coordinates;onInspect(coords?coords[1]:e.lngLat.lat,this.wrapLongitude(coords?coords[0]:e.lngLat.lng));});
    this.map.on('movestart',()=>this.hud('Click a location to inspect'));
    this.map.on('dragstart',()=>this.map.getContainer().classList.add('is-dragging'));
    this.map.on('dragend',()=>this.map.getContainer().classList.remove('is-dragging'));
    let hoverFrame=null;
    this.map.on('mousemove',e=>{this.hoverPosition=e.lngLat;if(hoverFrame)return;hoverFrame=requestAnimationFrame(()=>{hoverFrame=null;const {lat,lng}=this.hoverPosition,lon=this.wrapLongitude(lng),info=onHover?.(lat,lon);this.hud(`${Math.abs(lat).toFixed(2)}° ${lat>=0?'N':'S'} · ${Math.abs(lon).toFixed(2)}° ${lon>=0?'E':'W'}${info?' · '+info:''}`);});});
    this.map.getCanvas().addEventListener('mouseleave',()=>this.hud('Click a location to inspect'));
    this.map.getCanvas().addEventListener('keydown',e=>{if(e.key==='Home'||e.key==='Escape'){e.preventDefault();this.fit();}if(e.key==='Enter'){const c=this.map.getCenter();onInspect(c.lat,this.wrapLongitude(c.lng));}});
    new ResizeObserver(()=>{if(document.getElementById('map').offsetWidth)this.map.resize();}).observe(document.getElementById('map'));
  }
  hud(text){document.getElementById('map-hud').textContent=text;}
  wrapLongitude(lon){return ((lon+180)%360+360)%360-180;}
  requestTile(url,signal){const match=url.match(/comfy-climate:\/\/(\d+)\/(\d+)\/(\d+)\/(\d+)/);if(!match)return Promise.reject(new Error('Invalid climate tile URL'));const [,revision,z,x,y]=match.map(Number);if(signal.aborted)return Promise.reject(new DOMException('Tile cancelled','AbortError'));return new Promise((resolve,reject)=>{const id=++this.tileSequence,cancel=()=>{this.tileRequests.delete(id);this.tileWorker.postMessage({type:'cancel',id});reject(new DOMException('Tile cancelled','AbortError'));};signal.addEventListener('abort',cancel,{once:true});this.tileRequests.set(id,{resolve,reject,detach:()=>signal.removeEventListener('abort',cancel)});this.tileWorker.postMessage({type:'tile',id,revision,z,x,y,ratio:Math.min(2,devicePixelRatio||1)});});}
  installClimate(){if(!this.loaded||!this.field||!this.geometry)return;const tiles=[`comfy-climate://${this.revision}/{z}/{x}/{y}`];if(this.map.getSource('climate'))this.map.getSource('climate').setTiles(tiles);else{this.map.addSource('climate',{type:'raster',tiles,tileSize:256,minzoom:0,maxzoom:16});const before=this.map.getStyle().layers.find(l=>l.id!=='background')?.id;this.map.addLayer({id:'climate',type:'raster',source:'climate',paint:{'raster-opacity':1,'raster-fade-duration':0,'raster-resampling':'nearest'}},before);}}
  updateTiles(){if(!this.field||!this.geometry)return;this.revision++;this.tileWorker.postMessage({type:'field',revision:this.revision,field:this.field,latitude:this.meta.latitude[0],longitude:this.meta.longitude[0],rgb:this.rgb,high:this.high,display:this.display,matchMask:this.matchMask});this.installClimate();}
  setMatch(settings,scores,days){this.matchMask=null;if(settings.enabled&&scores&&days){this.matchMask=new Uint8Array(scores.length);for(let i=0;i<scores.length;i++)this.matchMask[i]=Number.isFinite(scores[i])&&Number.isFinite(days[i])&&scores[i]>=settings.score&&days[i]>=settings.days?1:0;}}
  setData(values,meta,nodeGrid,view){this.meta=meta;this.low=0;this.high=view==='days'?150:10;this.rgb=meta.palette.map(h=>h.match(/[a-f0-9]{2}/gi).map(v=>parseInt(v,16)));this.field=new Float64Array(values);
    // Preserve the previous coast extension exactly; it affects display only.
    if(this.coastGrid!==nodeGrid){this.coastGrid=nodeGrid;this.coastSources=[];for(let y=0;y<360;y++)for(let x=0;x<720;x++){const i=y*720+x;if(nodeGrid[i]>=0)continue;let best=Infinity,index=-1;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const yy=y+dy;if(yy<0||yy>=360)continue;const j=yy*720+((x+dx+720)%720),d=dx*dx+dy*dy;if(nodeGrid[j]>=0&&d<best){best=d;index=j;}}if(index>=0&&best<=2.25)this.coastSources.push([i,index]);}}
    for(const [i,j] of this.coastSources)this.field[i]=values[j];this.updateTiles();
  }
  setDisplay(mode){if(!['smooth','grid'].includes(mode)||mode===this.display)return;this.display=mode;this.updateTiles();}
  setBorders(geo){this.geometry=geo;this.labels=geo.features.filter(f=>f.properties.name!=='Antarctica').map(f=>({name:f.properties.name,lat:f.properties.label[0],lon:f.properties.label[1]}));this.tileWorker.postMessage({type:'geometry',geo});}
  setStates(geo){this.states=geo;this.installStates();}
  installStates(){if(!this.loaded||!this.states||this.map.getSource('us-state-labels'))return;const before=this.map.getStyle().layers.find(l=>l.type==='symbol')?.id;
    this.map.addSource('us-state-borders',{type:'geojson',data:this.states});
    this.map.addLayer({id:'us-state-borders',type:'line',source:'us-state-borders',minzoom:2,paint:{'line-color':'#334d6d','line-width':1,'line-opacity':.65}},before);
    this.map.addSource('us-state-labels',{type:'geojson',data:{type:'FeatureCollection',features:this.states.features.map(f=>({type:'Feature',geometry:{type:'Point',coordinates:[f.properties.label[1],f.properties.label[0]]},properties:{name:f.properties.name,abbr:f.properties.abbr}}))}});
    this.map.addLayer({id:'us-state-labels',type:'symbol',source:'us-state-labels',minzoom:2,maxzoom:5,layout:{'text-field':['get','abbr'],'text-font':['Noto Sans Regular'],'text-size':11,'text-padding':5},paint:{'text-color':'#0a2463','text-halo-color':'#ffffff','text-halo-width':1.5}},before);this.stateZoom();
  }
  stateZoom(){if(this.map.getLayer('us-state-labels')){const min=this.region==='usa'?2:4.5;this.map.setLayerZoomRange('us-state-labels',min,5);this.map.setLayerZoomRange('us-state-borders',min,16);}}
  setPlaces(places){this.places=places;}
  setRegion(region){this.region=region;this.stateZoom();this.fit();}
  boundsForMap(b){return [[b[0][1],b[0][0]],[b[1][1],b[1][0]]];}
  fit(){const b=this.region==='usa'?this.usaViews[this.usaView]:this.regions[this.region];this.map.fitBounds(this.boundsForMap(b),{padding:20,duration:0});}
  setUSAView(view){this.usaView=view;this.fit();}
  focus(lat,lon,zoom=7){this.map.easeTo({center:[lon,lat],zoom,duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:550});}
  fitFeature(feature){if(feature.properties.name==='Alaska'||feature.properties.name==='Hawaii'){this.setUSAView(feature.properties.name.toLowerCase());return;}const bounds=new maplibregl.LngLatBounds(),visit=coordinates=>{if(typeof coordinates[0]==='number')bounds.extend(coordinates);else coordinates.forEach(visit);};visit(feature.geometry.coordinates);this.map.fitBounds(bounds,{padding:30,maxZoom:7,duration:0});}
  mark(lat,lon){if(this.selected)this.selected.setLngLat([lon,lat]);else{const element=document.createElement('div');element.className='climate-point';element.setAttribute('aria-hidden','true');this.selected=new maplibregl.Marker({element,anchor:'center'}).setLngLat([lon,lat]).addTo(this.map);}}
  clearMarker(){if(this.selected){this.selected.remove();this.selected=null;}}
  wrapColumn(x){return x>=0&&x<720?x:((x%720)+720)%720;}
  sample(fx,fy){if(!this.field)return NaN;const ny=Math.max(0,Math.min(359,Math.round(fy))),nx=this.wrapColumn(Math.round(fx)),nearest=this.field[ny*720+nx];if(this.display==='grid'||!Number.isFinite(nearest))return nearest;const y=Math.max(0,Math.min(358,Math.floor(fy))),x=Math.floor(fx),dx=fx-x,dy=Math.max(0,Math.min(1,fy-y)),a=this.field[y*720+this.wrapColumn(x)],b=this.field[y*720+this.wrapColumn(x+1)],c=this.field[(y+1)*720+this.wrapColumn(x)],d=this.field[(y+1)*720+this.wrapColumn(x+1)];if(!Number.isFinite(a)||!Number.isFinite(b)||!Number.isFinite(c)||!Number.isFinite(d))return nearest;return a*(1-dx)*(1-dy)+b*dx*(1-dy)+c*(1-dx)*dy+d*dx*dy;}
  writeColor(data,o,v){if(!Number.isFinite(v)){data[o]=data[o+1]=data[o+2]=239;}else{const q=Math.min(1,Math.max(0,(v-this.low)/(this.high-this.low)))*12,a=Math.min(11,Math.floor(q));for(let c=0;c<3;c++)data[o+c]=Math.floor(this.rgb[a][c]+(this.rgb[a+1][c]-this.rgb[a][c])*(q-a)+.5);}data[o+3]=255;}
  exportClimate(ctx,x,y,w,h,bounds){const canvas=document.createElement('canvas'),ww=Math.round(w),hh=Math.round(h);canvas.width=ww;canvas.height=hh;const tc=canvas.getContext('2d'),im=tc.createImageData(ww,hh),west=bounds[0][1],east=bounds[1][1],south=bounds[0][0],north=bounds[1][0];for(let yy=0;yy<hh;yy++){const lat=north-(yy+.5)/hh*(north-south),fy=(this.meta.latitude[0]-lat)/.5;for(let xx=0;xx<ww;xx++){const lon=west+(xx+.5)/ww*(east-west),fx=(lon-this.meta.longitude[0])/.5;this.writeColor(im.data,(yy*ww+xx)*4,this.sample(fx,fy));}}tc.putImageData(im,0,0);const clip=new Path2D();for(const f of this.geometry.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];for(const polygon of polygons)for(const ring of polygon){ring.forEach((p,i)=>{const px=x+(p[0]-west)/(east-west)*w,py=y+(north-p[1])/(north-south)*h;if(i)clip.lineTo(px,py);else clip.moveTo(px,py);});clip.closePath();}}ctx.save();ctx.fillStyle='#fff';ctx.fillRect(x,y,w,h);ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.clip(clip);ctx.drawImage(canvas,x,y,w,h);ctx.restore();}
  stateAt(lat,lon){if(!this.states)return null;const inside=ring=>{let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>lat)!==(b[1]>lat)&&lon<(b[0]-a[0])*(lat-a[1])/(b[1]-a[1])+a[0])yes=!yes;}return yes;};for(const f of this.states.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];if(polygons.some(p=>inside(p[0])&&!p.slice(1).some(inside)))return f.properties.name;}return null;}
  exportBorders(ctx,x,y,w,h,bounds){if(!this.geometry)return;const west=bounds[0][1],east=bounds[1][1],south=bounds[0][0],north=bounds[1][0],project=p=>[x+(p[0]-west)/(east-west)*w,y+(north-p[1])/(north-south)*h];ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.strokeStyle='#435b68';ctx.lineWidth=.8;ctx.globalAlpha=.65;for(const f of this.geometry.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];ctx.beginPath();for(const polygon of polygons)for(const ring of polygon){ring.forEach((p,i)=>{const q=project(p);if(i)ctx.lineTo(...q);else ctx.moveTo(...q);});ctx.closePath();}ctx.stroke();}ctx.globalAlpha=1;ctx.font='22px Arial';ctx.textAlign='center';ctx.textBaseline='middle';const boxes=[];this.exportStates(ctx,project,bounds,boxes);for(const item of this.labels){if(this.region==='usa'&&item.name==='United States of America')continue;const q=project([item.lon,item.lat]),tw=ctx.measureText(item.name).width,box=[q[0]-tw/2-8,q[1]-16,q[0]+tw/2+8,q[1]+16];if(q[0]<x||q[0]>x+w||q[1]<y||q[1]>y+h||boxes.some(b=>box[0]<b[2]&&box[2]>b[0]&&box[1]<b[3]&&box[3]>b[1]))continue;boxes.push(box);ctx.strokeStyle='#ffffff';ctx.lineWidth=4;ctx.strokeText(item.name,...q);ctx.fillStyle='#294453';ctx.fillText(item.name,...q);}ctx.restore();}
  exportStates(ctx,project,bounds,boxes){if(!this.states||this.region!=='usa')return;ctx.strokeStyle='#153e3c';ctx.lineWidth=1.4;ctx.globalAlpha=.8;for(const f of this.states.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];ctx.beginPath();for(const polygon of polygons)for(const ring of polygon){ring.forEach((p,i)=>{const q=project(p);if(i)ctx.lineTo(...q);else ctx.moveTo(...q);});ctx.closePath();}ctx.stroke();}ctx.globalAlpha=1;ctx.font='bold 20px Arial';for(const f of this.states.features){const [lat,lon]=f.properties.label;if(lat<bounds[0][0]||lat>bounds[1][0]||lon<bounds[0][1]||lon>bounds[1][1])continue;const name=f.properties.name,q=project([lon,lat]),tw=ctx.measureText(name).width,box=[q[0]-tw/2-6,q[1]-12,q[0]+tw/2+6,q[1]+12];if(boxes.some(b=>box[0]<b[2]&&box[2]>b[0]&&box[1]<b[3]&&box[3]>b[1]))continue;boxes.push(box);ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.strokeText(name,...q);ctx.fillStyle='#153e3c';ctx.fillText(name,...q);}ctx.font='22px Arial';}
  get exportBounds(){return this.region==='usa'?this.usaViews[this.usaView]:this.region==='europe'?this.regions.europe:[[-90,-180],[90,180]];}
}
window.GeographicMap=GeographicMap;
